style.css:
/* ? КОСМИЧЕСКИЙ ЧЕРНЫЙ ФОН */
body {
  background-color: #05070b !important;
  background-image: radial-gradient(circle at top, #0b1a2a, #05070b 70%) !important;
}

/* ? ВЕСЬ ТЕКСТ ГОЛУБОЙ */
* {
  color: #6fd3ff !important;
  font-family: "Inter", "Segoe UI", sans-serif !important;
}

/* ✨ Сообщения */
div {
  background-color: transparent !important;
}

/* ? Сообщения GPT */
div[class*="assistant"] {
  background: rgba(10, 25, 45, 0.6) !important;
  border-radius: 16px !important;
  box-shadow: 0 0 20px rgba(90, 180, 255, 0.25) !important;
}

/* ? Твои сообщения */
div[class*="user"] {
  background: rgba(5, 15, 30, 0.8) !important;
  border-radius: 16px !important;
  box-shadow: 0 0 12px rgba(60, 140, 220, 0.2) !important;
}

/* ? Поле ввода */
textarea {
  background: #02040a !important;
  color: #9be5ff !important;
  border: 1px solid #3fa9ff !important;
  border-radius: 14px !important;
}

/* ? Кнопки */
button {
  background: linear-gradient(90deg, #3fa9ff, #6fd3ff) !important;
  color: #00131f !important;
  border-radius: 14px !important;
}

/* ? Скроллбар (если поддерживается) */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-thumb {
  background: #2a7dbb;
  border-radius: 10px;
}
